      "missing_context": [
        "Привязка расчетной греющей стороны отопления 3-зоны к маркированным участкам схемы.",
        "Ведомость участков или детализация материала, связывающая эти участки со строкой спецификации и толщиной стенки."
      ],
      "context_queries": [
        "ведомость трубопроводов",
        "Трубопровод отопления 3-зоны",
        "Д=76х3,5",
        "Ø76 × 3,0",
        "blk_94b58ecf5d404f7d90c272d267eb2e48",
